#include <iostream>
#include <string>
#include <vector>

int main() {
    int numberInput;
    std::cin >> numberInput;
    std::string inputString;
    std::cin >> inputString;

    std::string workingString = inputString;
    std::string bracketsHolder = "_";
    int startIdx = -1;
    int totalLenStr = workingString.length();

    for (int index = 0; index < totalLenStr; index++) {
        char currentChar = workingString[index];
        if (currentChar == '(') {
            startIdx = index;
        } else if (currentChar == ')') {
            bracketsHolder += workingString.substr(startIdx + 1, index - startIdx - 1) + "_";
            workingString = workingString.substr(0, startIdx) + "_" + workingString.substr(index + 1);
            totalLenStr = workingString.length();
            index = startIdx - 1;
            startIdx = -1;
        }
    }

    // Count total brackets
    std::vector<std::string> bracketPartsArr;
    size_t pos = 0;
    while ((pos = bracketsHolder.find('_')) != std::string::npos) {
        std::string token = bracketsHolder.substr(0, pos);
        bracketPartsArr.push_back(token);
        bracketsHolder.erase(0, pos + 1);
    }
    // Add the last part if not empty
    if (!bracketsHolder.empty()) {
        bracketPartsArr.push_back(bracketsHolder);
    }

    int bracketCountTotal = 0;
    for (const auto& part : bracketPartsArr) {
        if (!part.empty()) {
            bracketCountTotal++;
        }
    }

    // Count max segment length
    std::vector<std::string> segmentsArr;
    size_t start = 0;
    size_t end;
    while ((end = workingString.find('_', start)) != std::string::npos) {
        segmentsArr.push_back(workingString.substr(start, end - start));
        start = end + 1;
    }
    // Add the last segment
    if (start < workingString.length()) {
        segmentsArr.push_back(workingString.substr(start));
    }

    int maxSegmentLen = 0;
    for (const auto& segment : segmentsArr) {
        if (segment.length() > maxSegmentLen) {
            maxSegmentLen = segment.length();
        }
    }

    std::cout << maxSegmentLen << " " << bracketCountTotal << std::endl;

    return 0;
}
